            ui(()->context.startForegroundService(new Intent(context,RecorderService.class).setAction("start").putExtra("id",micId)));until(()->RecorderService.active,8);Thread.sleep(1300);check(RecorderService.capturedBytes>16000,"real_audio_record_pcm_capture");
            ui(activity::showRecorder);screen("03-phone-recording");ui(()->context.startService(new Intent(context,RecorderService.class).setAction("pause")));Thread.sleep(250);long frozen=RecorderService.capturedBytes;Thread.sleep(900);check(RecorderService.paused&&RecorderService.capturedBytes==frozen,"pause_excludes_audio_and_duration");
            ui(()->context.startService(new Intent(context,RecorderService.class).setAction("pause")));Thread.sleep(1000);check(RecorderService.capturedBytes>frozen,"resume_continues_local_recording");ui(()->context.startService(new Intent(context,RecorderService.class).setAction("stop")));until(()->!RecorderService.active&&!RecorderService.finishing,12);
            mic=store.draft(micId);File audio=new File(mic.getString("path"));byte[] micBytes=Files.readAllBytes(audio.toPath());check(micBytes.length>44&&ByteBuffer.wrap(micBytes,40,4).order(ByteOrder.LITTLE_ENDIAN).getInt()==micBytes.length-44,"saved_pcm_wav_has_complete_header");
            check(mic.optString("recording_id").isEmpty(),"stop_keeps_audio_local_until_user_saves");ui(()->activity.saveRecording(micId));screen("04-save-recording");MediaPlayer player=new MediaPlayer();try{player.setDataSource(audio.getAbsolutePath());player.prepare();player.start();Thread.sleep(250);check(player.getCurrentPosition()>0,"saved_recording_plays_locally");}finally{player.release();}
            JSONObject interrupted=store.newDraft("Teno interrupted capture acceptance",".wav");File interruptedAudio=new File(interrupted.getString("path"));Files.write(interruptedAudio.toPath(),micBytes);try(RandomAccessFile f=new RandomAccessFile(interruptedAudio,"rw")){f.seek(0);f.write(JwdAudio.wavHeader(0));}interrupted.put("status","recording");store.save(interrupted);store.recoverRecordings();check(store.draft(interrupted.getString("id")).optString("status").equals("local"),"interrupted_capture_recovered_for_upload");store.deleteDraft(interrupted);
